[{'from': 'system', 'value': 'You are a helpful assistant that answers in JSON. Here's the json schema you must adhere to:
<schema>
{"query": {"type": "string", "description": "The user's query to be processed by the agentic framework."}, "context": {"type": "object", "description": "Contextual information relevant to the user's query.", "properties": {"observations": {"type": "string", "description": "User's observations related to bird populations."}, "affectedSpecies": {"type": "array", "items": {"type": "string"}, "description": "List of bird species affected by urban development."}, "potentialCauses": {"type": "array", "items": {"type": "string"}, "description": "Potential causes of changes in bird populations."}, "conservationQuestions": {"type": "string", "description": "Questions regarding conservation efforts."}}}, "intent": {"type": "string", "description": "The inferred intent behind the user's query."}, "response": {"type": "object", "description": "The structured response generated by the agentic framework.", "properties": {"analysis": {"type": "string", "description": "Expert analysis of the impact on bird populations."}, "recommendations": {"type": "array", "items": {"type": "string"}, "description": "Recommendations for conservation efforts."}}}}
</schema>
