function kthSmallest = findKthSmallest(matrix, k)
 [m, n] = size(matrix);
 if k > m * n
 error('k is larger than the number of elements in the matrix');
 end
 flatMatrix = reshape(matrix, 1, m * n);
 kthSmallest = quickSelect(flatMatrix, k);
end
function kthSmallest = quickSelect(array, k)
 n = length(array);
 pivotIndex = randi(n);
 pivot = array(pivotIndex);
 left = [];
 right = [];
 for i = 1:n
 if i == pivotIndex
 continue;
 end
 if array(i) < pivot
 left = [left, array(i)];
 else
 right = [right, array(i)];
 end
 end
 if k <= length(left)
 kthSmallest = quickSelect(left, k);
 elseif k == length(left) + 1
 kthSmallest = pivot;
 else
 kthSmallest = quickSelect(right, k - length(left) - 1);
 end
end
