// Importing data from a CSV file
guard let filepath = Bundle.main.path(forResource: "smartphone_data", ofType: "csv") else { return }
guard let fileContents = try? String(contentsOfFile: filepath) else { return }
let lines = fileContents.components(separatedBy: .newlines)
// Extracting market share information for given quarters
var marketShare: [String: [Double]] = [:]
for line in lines {
 let fields = line.components(separatedBy: ",")
 if fields.count == 4 && fields[2].starts(with: "Q") {
 let quarter = fields[1] + "_" + fields[2]
 if marketShare[quarter] == nil {
 marketShare[quarter] = []
 }
 marketShare[quarter]?.append(Double(fields[3]) ?? 0)
 }
}
// Calculating percentage change in market share for each quarter
for (quarter, share) in marketShare {
 let marketShareChange = (share.last ?? 0 - share.first ?? 0) / share.first ?? 0 * 100
 print("The percentage change in market share from (quarter) is (marketShareChange)%")
}
```
And here's a Shell command that can extract market share data from a CSV file and save it to a new CSV file for each quarter:
```bash
#!/bin/bash
filename="smartphone_data.csv"
while read -r line; do
 brand=$(echo "$line" | cut -d ',' -f 1)
 year=$(echo "$line" | cut -d ',' -f 2)
 quarter=$(echo "$line" | cut -d ',' -f 3)
 share=$(echo "$line" | cut -d ',' -f 4)
 echo "$line" >> "${brand}_${year}_${quarter}.csv"
done < "$filename"
```
Note: This Shell command assumes that the CSV file has the same format as the given prompt and that the columns are in the order: Brand, Year, Quarter, and MarketShare. Also, it creates a separate CSV file for each quarter and each brand. You can modify it to suit your needs.'}
